/*
 * Modified by Actuna Sp. z o.o.:
 *   #45: the event-log of a command hides the credentials of URLs (command line and output,
 *   the output is logged by lines, so a URL split between chunks is still recognised)
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * Run system commands with event-log integration
 * @mixin @node-red/util_exec
 */

const child_process = require('child_process');
const events = require("./events");
const util = require('./util');
const maskUrl = require('./maskUrl');

function logLines(id,type,data,secrets) {
    events.emit("event-log", {id:id,payload:{ts: Date.now(),data:maskUrl.maskUrlCredentials(data,secrets),type:type}});
}

// The output arrives in arbitrary chunks, so a URL can be split between two of
// them. The output of one stream is logged by lines (a line ends with \n or \r);
// the rest is kept until the line is complete or the stream ends. A line that is
// longer than MAX_LINE is first masked as a whole (so a complete URL or secret is
// hidden wherever it would be cut), then logged up to its last white space that is at
// least KEEP_TAIL characters before the end - or up to that point when there is none.
// The last KEEP_TAIL characters stay pending, so a URL or a secret that is not complete
// yet (no "@" so far) is completed by the next chunk and masked then.
const MAX_LINE = 65536;
const KEEP_TAIL = 4096;
function lineLogger(id,type,secrets) {
    let pending = "";
    return {
        write: function(str) {
            pending += str;
            const end = Math.max(pending.lastIndexOf("\n"),pending.lastIndexOf("\r"));
            if (end >= 0) {
                logLines(id,type,pending.substring(0,end+1),secrets);
                pending = pending.substring(end+1);
            }
            if (pending.length > MAX_LINE) {
                const masked = maskUrl.maskUrlCredentials(pending,secrets);
                const limit = masked.length - KEEP_TAIL;
                if (limit > 0) {
                    const head = masked.substring(0,limit);
                    const space = Math.max(head.lastIndexOf(" "),head.lastIndexOf("\t"));
                    const cut = space >= 0 ? space + 1 : limit;
                    logLines(id,type,masked.substring(0,cut),secrets);
                    pending = masked.substring(cut);
                } else {
                    pending = masked;
                }
            }
        },
        flush: function() {
            if (pending.length > 0) {
                logLines(id,type,pending,secrets);
                pending = "";
            }
        }
    };
}

module.exports = {
    /**
     * Run a system command with stdout/err being emitted as 'event-log' events
     * on the @node-red/util/events handler.
     *
     * The main arguments to this function are the same as passed to `child_process.spawn`
     *
     * @param {String} command - the command to run
     * @param {Array}  args - arguments for the command
     * @param {Object} options - options to pass child_process.spawn
     * @param {Boolean} emit - whether to emit events to the event-log for each line of stdout/err
     * @param {String[]} [secrets] - literal secrets (for example the user info of a URL) to hide
     *                   in the event-log, in addition to the credentials of URLs found there
     * @return {Promise} A promise that resolves (rc=0) or rejects (rc!=0) when the command completes. The value
     *                   of the promise is an object of the form:
     *
     *       {
     *           code: <exit code>,
     *           stdout: <standard output from the command>,
     *           stderr: <standard error from the command>
     *       }

     * @memberof @node-red/util_exec
     */
    run: function(command,args,options,emit,secrets) {
        var invocationId = util.generateId();

        emit && events.emit("event-log", {ts: Date.now(),id:invocationId,payload:{ts: Date.now(),data:maskUrl.maskUrlCredentials(command+" "+args.join(" "),secrets)}});

        return new Promise((resolve, reject) => {
            let stdout = "";
            let stderr = "";
            const outLog = emit && lineLogger(invocationId,"out",secrets);
            const errLog = emit && lineLogger(invocationId,"err",secrets);
            let child
            if (args && options.shell) {
                // If we are using a shell, we need to join the args into a single string
                // as passing a separate array of args is deprecated in Node 24
                command = [command].concat(args).join(" ");
                child = child_process.spawn(command, options)
            } else {
                child = child_process.spawn(command, args, options);
            }
            child.stdout.on('data', (data) => {
                const str = ""+data;
                stdout += str;
                emit && outLog.write(str);
            });
            child.stderr.on('data', (data) => {
                const str = ""+data;
                stderr += str;
                emit && errLog.write(str);
            });
            child.on('error', function(err) {
                stderr = err.toString();
                emit && errLog.write(stderr);
                emit && errLog.flush();
            })
            child.on('close', (code) => {
                let result = {
                    code: code,
                    stdout: stdout,
                    stderr: stderr
                }
                if (emit) {
                    outLog.flush();
                    errLog.flush();
                    events.emit("event-log", {id:invocationId,payload:{ts: Date.now(), data:"rc="+code, end: true}});
                }

                if (code === 0) {
                    resolve(result)
                } else {
                    reject(result);
                }
            });
        })
    }
}
